<?php require __DIR__.'/../app/bootstrap.php';admin_required();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));if($name){try{$s=db()->prepare('INSERT INTO categories(name,slug,sort_order) VALUES(?,?,?)');$s->execute([$name,$slug,(int)($_POST['sort_order']??0)]);header('Location: '.url('admin/categories.php?saved=1'));exit;}catch(Throwable $t){$error='Could not save category. Check whether its slug already exists.';}}else{$error='Category name is required.';}}$cats=db()->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.sort_order,c.name')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categories — NEXT TECH Admin</title><link rel="stylesheet" href="<?=e(url('assets/css/style.css'))?>"></head><body class="admin-body"><aside class="admin-sidebar"><a class="wordmark" href="<?=e(url('admin/index.php'))?>"><span>NEXT</span> <b>TECH</b></a><a href="<?=e(url('admin/index.php'))?>">Dashboard</a><a href="<?=e(url('admin/products.php'))?>">Products</a><a class="active" href="<?=e(url('admin/categories.php'))?>">Categories</a><a href="<?=e(url('index.php'))?>">View Store</a><a href="<?=e(url('admin/logout.php'))?>">Logout</a></aside><main class="admin-main"><div class="admin-top"><h1>Categories</h1></div><?php if($error):?><p class="form-error"><?=e($error)?></p><?php endif;?><form class="admin-panel form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>New category name<input name="name" required></label><label>Slug (optional)<input name="slug"></label><label>Sort order<input type="number" name="sort_order" value="0"></label><div><button class="btn btn-primary">Add Category</button></div></form><div class="admin-panel table-wrap" style="margin-top:20px"><table><thead><tr><th>Category</th><th>Slug</th><th>Products</th><th>Visibility</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=(int)$c['product_count']?></td><td><?=$c['is_active']?'Active':'Hidden'?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>